    p=subprocess.Popen(["/workspace/executable","/tmp/data.txt"], stdin=stdin, stdout=stdout, stderr=subprocess.PIPE, close_fds=True)
    # close slaves in parent
    try: os.close(slave_in)
    except: pass
    try: os.close(slave_out)
    except: pass
    time.sleep(0.6)
    print("poll", p.poll())
    # nonblock master read
    for m,name in [(master_in,"master_in"),(master_out,"master_out")]:
