use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};

#[derive(Debug, Clone)]
pub struct Node {
    pub name: String,
    pub full_name: String,
    pub value: u64,
    pub children: Vec<Node>,
}

impl Node {
    pub fn new(name: &str, full_name: String) -> Self {
        Self { name: name.to_string(), full_name, value: 0, children: Vec::new() }
    }
    fn find_child(&mut self, name: &str) -> &mut Node {
        if let Some(pos) = self.children.iter().position(|c| c.name == name) {
            &mut self.children[pos]
        } else {
            let full = if self.full_name.is_empty() {
                name.to_string()
            } else {
                format!("{};{}", self.full_name, name)
            };
            self.children.push(Node::new(name, full));
            self.children.last_mut().unwrap()
        }
    }
    pub fn insert(&mut self, frames: &[&str], count: u64) {
        self.value = self.value.wrapping_add(count);
        if frames.is_empty() { return; }
        let child = self.find_child(frames[0]);
        child.insert(&frames[1..], count);
    }
    pub fn sort_sorted(&mut self) {
        // sort ascending by value then reverse (observed behaviour)
        self.children.sort_by(|a, b| a.value.cmp(&b.value));
        self.children.reverse();
        for c in &mut self.children { c.sort_sorted(); }
    }
    pub fn max_depth(&self) -> usize {
        if self.children.is_empty() { 0 } else { 1 + self.children.iter().map(|c| c.max_depth()).max().unwrap_or(0) }
    }
}

pub struct ParsedLine {
    pub frames_str: String,
    pub frames: Vec<String>,
    pub count: u64,
}

pub fn parse_lines(data: &str) -> Vec<ParsedLine> {
    let mut out = Vec::new();
    for line in data.split('\n') {
        if let Some((stack, count_s)) = line.rsplit_once(' ') {
            if stack.is_empty() { continue; }
            if let Ok(count) = count_s.parse::<u64>() {
                let frames: Vec<String> = stack.split(';').map(|s| s.to_string()).collect();
                out.push(ParsedLine { frames_str: stack.to_string(), frames, count });
            }
        }
    }
    out
}

pub fn build_tree(lines: &[ParsedLine], sorted: bool) -> Node {
    let mut root = Node { name: "all".to_string(), full_name: String::new(), value: 0, children: Vec::new() };
    for line in lines {
        if line.count == 0 { continue; }
        let refs: Vec<&str> = line.frames.iter().map(|s| s.as_str()).collect();
        root.insert(&refs, line.count);
    }
    if sorted { root.sort_sorted(); }
    root
}

