pub struct Frame {
    pub name: String,
    pub full_name: String,
    pub value: u64,
    pub x: u16,
    pub y: usize,
    pub width: u16,
}

fn scale(v: u64, total: u64, width: u16) -> u16 {
    ((v as f64 / total as f64) * width as f64) as u16
}

pub fn build_frames(root: &Node, area_width: u16, zoom: Option<&str>) -> Vec<Frame> {
    let mut frames = Vec::new();
    if area_width == 0 { return frames; }
    // locate zoom node value / path
    let mut zoom_node: Option<&Node> = None;
    let mut zoom_value: u64 = root.value;
    if let Some(z) = zoom {
        if let Some(n) = find_by_full(root, z) {
            zoom_node = Some(n);
            zoom_value = n.value;
        }
    }
    if let Some(zn) = zoom_node {
        // ancestors: traverse down to zn
        let mut anc: Vec<&Node> = Vec::new();
        collect_path(root, &zn.full_name, &mut anc);
        // anc[0]=root ... last = zn
        for (i, n) in anc.iter().enumerate() {
            let (x, w) = if i == 0 {
                (0u16, scale(n.value, zoom_value, area_width))
            } else if *n as *const Node == zn as *const Node {
                (0u16, area_width)
            } else {
                // compute within parent using zoom as total
                let parent = anc[i-1];
                // offset within parent: sum preceding siblings values
                let mut off_v: u64 = 0;
                for sib in &parent.children {
                    if sib.name == n.name && sib.full_name == n.full_name { break; }
                    off_v = off_v.wrapping_add(sib.value);
                }
                let x = scale(off_v, zoom_value, area_width);
                let w = scale(n.value, zoom_value, area_width);
                (x, w)
            };
            frames.push(Frame { name: n.name.clone(), full_name: n.full_name.clone(), value: n.value, x, y: i, width: w });
        }
        // descendants of zn
        let start_depth = anc.len();
        fn rec(node: &Node, depth: usize, abs_x_v: u64, zoom_value: u64, area_width: u16, frames: &mut Vec<Frame>) {
            let mut cur = abs_x_v;
            for child in &node.children {
                if child.value == 0 { continue; }
                let x = ((cur as f64 / zoom_value as f64) * area_width as f64) as u16;
                let w = ((child.value as f64 / zoom_value as f64) * area_width as f64) as u16;
                if w > 0 {
                    frames.push(Frame { name: child.name.clone(), full_name: child.full_name.clone(), value: child.value, x, y: depth, width: w });
                }
                rec(child, depth + 1, cur, zoom_value, area_width, frames);
                cur = cur.wrapping_add(child.value);
            }
        }
        rec(zn, start_depth, 0, zoom_value, area_width, &mut frames);
    } else {
        // no zoom
        frames.push(Frame { name: root.name.clone(), full_name: root.full_name.clone(), value: root.value, x: 0, y: 0, width: area_width });
        fn rec(node: &Node, depth: usize, abs_x_v: u64, total: u64, area_width: u16, frames: &mut Vec<Frame>) {
            let mut cur = abs_x_v;
            for child in &node.children {
                if child.value == 0 { continue; }
                let x = if total == 0 { 0 } else { ((cur as f64 / total as f64) * area_width as f64) as u16 };
                let w = if total == 0 { 0 } else { ((child.value as f64 / total as f64) * area_width as f64) as u16 };
                if w > 0 {
                    frames.push(Frame { name: child.name.clone(), full_name: child.full_name.clone(), value: child.value, x, y: depth, width: w });
                }
                rec(child, depth + 1, cur, total, area_width, frames);
                cur = cur.wrapping_add(child.value);
            }
        }
        if root.value > 0 {
            rec(root, 1, 0, root.value, area_width, &mut frames);
        }
    }
    frames
}

pub fn find_by_full<'a>(node: &'a Node, full: &str) -> Option<&'a Node> {
    if node.full_name == full { return Some(node); }
    for c in &node.children {
        if let Some(n) = find_by_full(c, full) { return Some(n); }
    }
    None
}

fn collect_path<'a>(node: &'a Node, full: &str, path: &mut Vec<&'a Node>) -> bool {
    path.push(node);
    if node.full_name == full { return true; }
    for c in &node.children {
        if collect_path(c, full, path) { return true; }
    }
    path.pop();
    false
}

pub fn is_ancestor_or_self(node_full: &str, zoom_full: &str) -> bool {
    if node_full.is_empty() { return true; } // root
    if zoom_full == node_full { return true; }
    zoom_full.len() > node_full.len()
        && zoom_full.starts_with(node_full)
        && zoom_full.as_bytes().get(node_full.len()) == Some(&b';')
}

// colours
pub fn hash_ratio(name: &str) -> f64 {
    let mut h = DefaultHasher::new();
    name.hash(&mut h);
    h.finish() as f64 / u64::MAX as f64
}

pub fn base_color(node_name: &str, full_name: &str) -> (u8, u8, u8) {
    let key = if full_name.is_empty() { node_name } else { full_name };
    let t = hash_ratio(key);
    let r = (205.0 + 50.0 * t) as u8;
    let g = (230.0 * t) as u8;
    let b = (55.0 * t) as u8;
    (r, g, b)
}

pub fn fg_for(bg: (u8, u8, u8)) -> (u8, u8, u8) {
    if bg.1 >= 109 { (10, 10, 10) } else { (225, 225, 225) }
}
