    if node.full_name == full { return Some(node); }
    for c in &node.children {
        if let Some(n) = find_by_full(c, full) { return Some(n); }
    }
    None
}

fn collect_path<'a>(node: &'a Node, full: &str, path: &mut Vec<&'a Node>) -> bool {
    path.push(node);
    if node.full_name == full { return true; }
    for c in &node.children {
        if collect_path(c, full, path) { return true; }
    }
    path.pop();
    false
}

pub fn is_ancestor_or_self(node_full: &str, zoom_full: &str) -> bool {
    if node_full.is_empty() { return true; } // root
    if zoom_full == node_full { return true; }
    zoom_full.len() > node_full.len()
        && zoom_full.starts_with(node_full)
        && zoom_full.as_bytes().get(node_full.len()) == Some(&b';')
}

// colours
pub fn hash_ratio(name: &str) -> f64 {
    let mut h = DefaultHasher::new();
    name.hash(&mut h);
    h.finish() as f64 / u64::MAX as f64
}

pub fn base_color(node_name: &str, full_name: &str) -> (u8, u8, u8) {
    let key = if full_name.is_empty() { node_name } else { full_name };
    let t = hash_ratio(key);
    let r = (205.0 + 50.0 * t) as u8;
    let g = (230.0 * t) as u8;
    let b = (55.0 * t) as u8;
    (r, g, b)
}

pub fn fg_for(bg: (u8, u8, u8)) -> (u8, u8, u8) {
    if bg.1 >= 109 { (10, 10, 10) } else { (225, 225, 225) }
}
