use crossterm::event::{KeyCode, KeyEvent, KeyModifiers};
use unicode_width::UnicodeWidthChar;

// A small single-line text input modelled on the behaviour observed
// in the reference (tui-input style):
// cursor is a byte index into `value`, always on a char boundary.
#[derive(Debug, Default, Clone)]
pub struct TextInput {
    pub value: String,
    pub cursor: usize, // byte index
}

fn is_word_char(c: char) -> bool {
    c.is_alphanumeric()
}

impl TextInput {
    pub fn new() -> Self {
        Self::default()
    }
    pub fn reset(&mut self) {
        self.value.clear();
        self.cursor = 0;
    }
    fn chars_before(&self) -> Vec<char> {
        self.value[..self.cursor].chars().collect()
    }
    fn prev_boundary(&self, from: usize) -> usize {
        self.value[..from].char_indices().last().map(|(i, _)| i).unwrap_or(0)
    }
    fn next_boundary(&self, from: usize) -> usize {
        self.value[from..]
            .char_indices()
            .nth(1)
            .map(|(i, _)| from + i)
            .unwrap_or(self.value.len())
    }
    // positions (byte) of each char start + len sentinel
    fn boundaries(&self) -> Vec<usize> {
        let mut v: Vec<usize> = self.value.char_indices().map(|(i, _)| i).collect();
        v.push(self.value.len());
        v
    }
    fn char_idx_of(&self, byte: usize) -> usize {
        self.value[..byte].chars().count()
    }
    fn byte_of_char(&self, ci: usize) -> usize {
        self.boundaries().into_iter().nth(ci).unwrap_or(self.value.len())
    }

    fn word_begin(&self) -> usize {
        // char-index based: skip non-word, then word
        let chars: Vec<char> = self.value.chars().collect();
        let mut i = self.char_idx_of(self.cursor);
        while i > 0 && !is_word_char(chars[i - 1]) {
            i -= 1;
        }
        while i > 0 && is_word_char(chars[i - 1]) {
            i -= 1;
        }
        self.byte_of_char(i)
    }
    fn word_end(&self) -> usize {
        let chars: Vec<char> = self.value.chars().collect();
        let mut i = self.char_idx_of(self.cursor);
        while i < chars.len() && !is_word_char(chars[i]) {
            i += 1;
        }
        while i < chars.len() && is_word_char(chars[i]) {
            i += 1;
        }
        self.byte_of_char(i)
    }

    // Returns true if the key was handled by the editor (for procedure
    // keys like Enter/Esc the caller handles them before calling this).
    pub fn handle(&mut self, key: KeyEvent) {
        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        let alt = key.modifiers.contains(KeyModifiers::ALT);
        match key.code {
            KeyCode::Char('c') if ctrl => {}
            KeyCode::Char('u') if ctrl => {
                self.value.clear();
                self.cursor = 0;
            }
            KeyCode::Char('w') if ctrl => {
                let wb = self.word_begin();
                self.value.replace_range(wb..self.cursor, "");
                self.cursor = wb;
            }
            KeyCode::Char('a') if ctrl => {
                self.cursor = 0;
            }
            KeyCode::Char('e') if ctrl => {
                self.cursor = self.value.len();
            }
            KeyCode::Char('k') if ctrl => {
                self.value.truncate(self.cursor);
            }
            KeyCode::Char('h') if ctrl => {
                self.backspace();
            }
            KeyCode::Char('d') if ctrl => {
                self.delete();
            }
            KeyCode::Char(c) if !ctrl && !alt => {
                self.value.insert(self.cursor, c);
                self.cursor = self.next_boundary(self.cursor);
            }
            KeyCode::Backspace if alt => {
                // Alt+Backspace: delete word before cursor. Crossterm may
                // report this as Char with ALT on some terminals; tmux
                // M-BSpace maps to Backspace+ALT.
                let wb = self.word_begin();
                self.value.replace_range(wb..self.cursor, "");
                self.cursor = wb;
            }
            KeyCode::Backspace => {
                self.backspace();
            }
            KeyCode::Delete if ctrl => {
                let we = self.word_end();
                self.value.replace_range(self.cursor..we, "");
            }
            KeyCode::Delete => {
                self.delete();
            }
            KeyCode::Left if ctrl => {
                self.cursor = self.word_begin();
            }
            KeyCode::Left => {
                if self.cursor > 0 {
                    self.cursor = self.prev_boundary(self.cursor);
                }
            }
            KeyCode::Right if ctrl => {
                self.cursor = self.word_end();
            }
            KeyCode::Right => {
                if self.cursor < self.value.len() {
                    self.cursor = self.next_boundary(self.cursor);
                }
            }
            KeyCode::Home => {
                self.cursor = 0;
            }
            KeyCode::End => {
                self.cursor = self.value.len();
            }
            _ => {}
        }
        // satisfy unused warnings for helper
        let _ = UnicodeWidthChar::width('x');
        let _ = self.chars_before();
    }

    fn backspace(&mut self) {
        if self.cursor > 0 {
            let p = self.prev_boundary(self.cursor);
            self.value.replace_range(p..self.cursor, "");
            self.cursor = p;
        }
    }
    fn delete(&mut self) {
        if self.cursor < self.value.len() {
            let n = self.next_boundary(self.cursor);
            self.value.replace_range(self.cursor..n, "");
        }
    }

    pub fn visual_cursor(&self) -> usize {
        self.value[..self.cursor]
            .chars()
            .map(|c| UnicodeWidthChar::width(c).unwrap_or(0))
            .sum()
    }
}
