use crate::flame::{self, Frame, Node};
use crate::input::TextInput;
use crate::stats::{self, SortBy, Stat};
use crossterm::{
    event::{self, Event, KeyCode, KeyEventKind, KeyModifiers},
    execute,
    terminal::{disable_raw_mode, enable_raw_mode, EnterAlternateScreen, LeaveAlternateScreen},
};
use ratatui::{backend::CrosstermBackend, Terminal};
use regex::Regex;
use std::collections::HashMap;
use std::io;
use std::time::{Duration, Instant};

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum View {
    Flamegraph,
    Top,
}

pub struct App {
    pub name: String,
    pub view: View,
    pub root: Node,
    pub stats: Vec<Stat>,
    pub total: u64,
    pub max_depth: usize, // number of rows incl root

    // flame state
    pub cursor_x: u16,
    pub cursor_y: usize,
    pub selected: Option<Frame>,
    pub offset_y: usize,
    pub zoomed: Option<String>, // full_name
    pub zoomed_value: u64,

    // search
    pub searching: bool,
    pub input: TextInput,
    pub search_pattern: Option<String>,
    pub search_regex: Option<Regex>,
    pub match_value: u64,

    // top state
    pub top_selected_abs: usize,
    pub top_offset: usize,
    pub sort_by: SortBy,

    // misc
    pub info: Option<String>,
    pub show_debug: bool,
    pub timings: HashMap<String, Duration>,
    pub area_width: u16,
    pub area_height: u16,
    pub quit: bool,
}

impl App {
    pub fn new(name: String, data: &str, sorted: bool, debug: bool) -> Self {
        let t0 = Instant::now();
        let lines = flame::parse_lines(data);
        let root = flame::build_tree(&lines, sorted);
        let stats = stats::build_stats(&lines);
        let total = root.value;
        let max_depth = root.max_depth() + 1;
        let elapsed = t0.elapsed();
        let mut timings = HashMap::new();
        timings.insert("flamegraph".to_string(), elapsed);
        Self {
            name,
            view: View::Flamegraph,
            root,
            stats,
            total,
            max_depth,
            cursor_x: 0,
            cursor_y: 0,
            selected: None,
            offset_y: 0,
            zoomed: None,
            zoomed_value: total,
            searching: false,
            input: TextInput::new(),
            search_pattern: None,
            search_regex: None,
            match_value: 0,
            top_selected_abs: 0,
            top_offset: 0,
            sort_by: SortBy::Own,
            info: None,
            show_debug: debug,
            timings,
            area_width: 0,
            area_height: 0,
            quit: false,
        }
    }

    pub fn frames(&self) -> Vec<Frame> {
        flame::build_frames(&self.root, self.area_width, self.zoomed.as_deref())
    }

    pub fn frame_at(&self, frames: &[Frame], x: u16, y: usize) -> Option<Frame> {
        frames
            .iter()
            .find(|f| f.y == y && x >= f.x && x < f.x.saturating_add(f.width))
            .cloned()
    }

    pub fn update_selected(&mut self) {
        let frames = self.frames();
        self.selected = self.frame_at(&frames, self.cursor_x, self.cursor_y);
    }

    fn ensure_visible(&mut self) {
        let h = self.area_height as usize;
        if h == 0 {
            return;
        }
        if self.cursor_y < self.offset_y {
            self.offset_y = self.cursor_y;
        } else if self.cursor_y >= self.offset_y + h {
            self.offset_y = self.cursor_y + 1 - h;
        }
    }

    fn move_cursor_to_frame(&mut self, f: &Frame) {
        self.cursor_x = f.x + f.width / 2;
        self.cursor_y = f.y;
        self.ensure_visible();
    }

    // ---- search helpers ----
    pub fn compute_match(&self, re: &Regex) -> u64 {
        fn rec(node: &Node, re: &Regex) -> u64 {
            if re.is_match(&node.name) {
                return node.value;
            }
            node.children.iter().map(|c| rec(c, re)).fold(0u64, |a, b| a.wrapping_add(b))
        }
        self.root
            .children
            .iter()
            .map(|c| rec(c, re))
            .fold(0u64, |a, b| a.wrapping_add(b))
    }

    fn set_search(&mut self, pattern: String) {
        match Regex::new(&pattern) {
            Ok(re) => {
                self.match_value = self.compute_match(&re);
                self.search_regex = Some(re);
                self.search_pattern = Some(pattern);
                self.top_offset = 0;
                self.top_selected_abs = 0;
            }
            Err(_) => {
                self.info = Some(format!("Invalid regex: {}", pattern));
            }
        }
    }

    fn matches_sorted(&self) -> Vec<Frame> {
        let Some(re) = &self.search_regex else {
            return Vec::new();
        };
        let mut frames = self.frames();
        frames.retain(|f| !(f.y == 0) && re.is_match(&f.name));
        frames.sort_by(|a, b| a.y.cmp(&b.y).then(a.x.cmp(&b.x)));
        frames
    }

    fn next_match(&mut self, forward: bool) {
        let matches = self.matches_sorted();
        if matches.is_empty() {
            return;
        }
        let cur = (self.cursor_y, self.cursor_x);
        let found = if forward {
            matches.iter().find(|f| (f.y, f.x + f.width / 2) > cur).cloned()
        } else {
            matches.iter().rev().find(|f| (f.y, f.x + f.width / 2) < cur).cloned()
        };
        if let Some(f) = found {
            self.move_cursor_to_frame(&f);
        }
    }

    fn reset(&mut self) {
        match self.view {
            View::Flamegraph => {
                self.cursor_x = self.area_width / 2;
                self.cursor_y = 0;
                self.offset_y = 0;
                self.zoomed = None;
                self.zoomed_value = self.total;
                self.search_pattern = None;
                self.search_regex = None;
                self.match_value = 0;
                self.info = None;
                self.searching = false;
                self.input.reset();
            }
            View::Top => {
                self.top_selected_abs = 0;
                self.top_offset = 0;
                self.search_pattern = None;
                self.search_regex = None;
                self.match_value = 0;
                self.info = None;
                self.searching = false;
                self.input.reset();
            }
        }
    }

    // ---- top helpers ----
    pub fn filtered_stats(&self) -> Vec<&Stat> {
        if let Some(re) = &self.search_regex {
            let f: Vec<&Stat> = self.stats.iter().filter(|s| re.is_match(&s.name)).collect();
            if f.is_empty() {
                self.stats.iter().collect()
            } else {
                f
            }
        } else {
            self.stats.iter().collect()
        }
    }

    // ---- main loop ----
    pub fn run(&mut self) -> io::Result<()> {
        enable_raw_mode()?;
        let mut stderr = io::stderr();
        execute!(stderr, EnterAlternateScreen)?;
        let backend = CrosstermBackend::new(stderr);
        let mut terminal = Terminal::new(backend)?;

        let mut first = true;
        let res = loop {
            if self.quit {
                break Ok(());
            }
            let t_render = Instant::now();
            let draw_res = terminal.draw(|frame| {
                crate::ui::draw(frame, self);
            });
            if let Err(e) = draw_res {
