    fn on_key(&mut self, key: crossterm::event::KeyEvent) {
        // Searching mode takes precedence (except procedure keys below).
        if self.searching {
            match key.code {
                KeyCode::Enter => {
                    let text = self.input.value.clone();
                    self.searching = false;
                    if text.is_empty() {
                        self.search_pattern = None;
                        self.search_regex = None;
                        self.match_value = 0;
                        self.top_offset = 0;
                        self.top_selected_abs = 0;
                    } else {
