                    }
                    self.input.reset();
                }
                KeyCode::Esc => {
                    self.searching = false;
                    self.input.reset();
                }
                _ => {
                    self.input.handle(key);
                }
            }
            return;
        }

        let ctrl = key.modifiers.contains(KeyModifiers::CONTROL);
        // quit keys (modifiers ignored like reference except plain char match via crossterm codes)
        match key.code {
            KeyCode::Char('q') => {
                self.quit = true;
                return;
            }
            KeyCode::Char('c') if ctrl => {
                self.quit = true;
                return;
            }
            _ => {}
        }

        match key.code {
            KeyCode::Tab => {
                self.info = None;
                self.view = match self.view {
                    View::Flamegraph => View::Top,
                    View::Top => View::Flamegraph,
                };
                return;
            }
            KeyCode::Char('?') if !ctrl => {
                self.info = None;
                self.show_debug = !self.show_debug;
                return;
            }
            KeyCode::Char('/') => {
                self.info = None;
                self.searching = true;
                self.input.reset();
                return;
            }
            _ => {}
        }

        match self.view {
            View::Flamegraph => self.on_key_flame(key),
            View::Top => self.on_key_top(key),
