    fn on_key_flame(&mut self, key: crossterm::event::KeyEvent) {
        let frames = self.frames();
        let mut handled = true;
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                if self
                    .frame_at(&frames, self.cursor_x, self.cursor_y + 1)
                    .is_some()
                {
                    self.cursor_y += 1;
                    self.ensure_visible();
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.cursor_y > 0 {
                    self.cursor_y -= 1;
                    self.ensure_visible();
                }
            }
            KeyCode::Char('h') | KeyCode::Left => {
                if let Some(cur) = self.frame_at(&frames, self.cursor_x, self.cursor_y) {
                    if cur.x > 0 {
                        if let Some(f) = self.frame_at(&frames, cur.x - 1, self.cursor_y) {
                            self.move_cursor_to_frame(&f);
                        }
                    }
                }
            }
            KeyCode::Char('l') | KeyCode::Right => {
                if let Some(cur) = self.frame_at(&frames, self.cursor_x, self.cursor_y) {
                    let nx = cur.x.saturating_add(cur.width);
                    if let Some(f) = self.frame_at(&frames, nx, self.cursor_y) {
                        self.move_cursor_to_frame(&f);
                    }
                }
            }
            KeyCode::Char('f') => {
                let h = self.area_height as usize;
                if h > 0 && self.max_depth > h {
                    let max_off = self.max_depth - h;
                    let new_off = std::cmp::min(self.offset_y + h, max_off);
                    if new_off != self.offset_y {
                        self.offset_y = new_off;
                        self.cursor_y = new_off;
                    }
                }
            }
            KeyCode::Char('b') => {
                let h = self.area_height as usize;
