                            let nfr = nfr.clone();
                            self.move_cursor_to_frame(&nfr);
                        }
                    }
                }
            }
            KeyCode::Esc => {
                // keep cursor on same logical frame
                let cur = self.frame_at(&frames, self.cursor_x, self.cursor_y);
                self.zoomed = None;
                self.zoomed_value = self.total;
                if let Some(cf) = cur {
                    let nf = self.frames();
                    if let Some(nfr) = nf.iter().find(|x| x.full_name == cf.full_name && x.y == cf.y) {
                        let nfr = nfr.clone();
                        self.move_cursor_to_frame(&nfr);
                    }
                }
            }
            KeyCode::Char('r') => {
                self.reset();
            }
            KeyCode::Char('n') => {
                self.next_match(true);
            }
            KeyCode::Char('N') => {
                self.next_match(false);
            }
            KeyCode::Char('#') => {
                if let Some(f) = self.frame_at(&frames, self.cursor_x, self.cursor_y) {
                    if f.y != 0 {
                        let pattern = format!("^{}$", regex::escape(&f.name));
                        self.set_search(pattern);
                    }
                }
            }
            KeyCode::Char('z') => {
                // handled (clears info) but otherwise no-op outside live mode
            }
            _ => {
                handled = false;
            }
        }
        if handled {
            self.info = None;
        }
    }

    fn on_key_top(&mut self, key: crossterm::event::KeyEvent) {
        let mut handled = true;
        match key.code {
            KeyCode::Char('j') | KeyCode::Down => {
                let len = self.filtered_stats().len();
                if len > 0 && self.top_selected_abs + 1 < len {
                    self.top_selected_abs += 1;
                }
            }
            KeyCode::Char('k') | KeyCode::Up => {
                if self.top_selected_abs > 0 {
                    self.top_selected_abs -= 1;
                }
            }
            KeyCode::Char('f') => {
                let h = self.area_height as usize;
                let len = self.filtered_stats().len();
                let max_off = len.saturating_sub(h);
                let new_off = std::cmp::min(self.top_offset + h, max_off);
                if new_off != self.top_offset {
                    self.top_offset = new_off;
                    self.top_selected_abs = new_off;
                }
            }
            KeyCode::Char('b') => {
                let h = self.area_height as usize;
                let new_off = self.top_offset.saturating_sub(h);
                if new_off != self.top_offset {
                    self.top_offset = new_off;
                    self.top_selected_abs = new_off;
                }
            }
            KeyCode::Char('1') => {
                self.sort_by = SortBy::Total;
                stats::sort_stats(&mut self.stats, SortBy::Total);
            }
            KeyCode::Char('2') => {
                self.sort_by = SortBy::Own;
                stats::sort_stats(&mut self.stats, SortBy::Own);
            }
            KeyCode::Char('r') => {
                self.reset();
            }
            KeyCode::Enter => {
                // index into the full sorted stats (preserves reference quirk with filters)
                if let Some(s) = self.stats.get(self.top_selected_abs) {
                    let name = s.name.clone();
                    let pattern = format!("^{}$", regex::escape(&name));
                    // set_search resets top cursor/offset
                    self.set_search(pattern);
                    self.view = View::Flamegraph;
                    self.cursor_x = self.area_width / 2;
                    self.cursor_y = 0;
                    self.offset_y = 0;
                } else {
                    self.view = View::Flamegraph;
                }
            }
            _ => {
                handled = false;
            }
        }
        if handled {
            self.info = None;
        }
    }
}
