    pub fn compute_match(&self, re: &Regex) -> u64 {
        fn rec(node: &Node, re: &Regex) -> u64 {
            if re.is_match(&node.name) {
                return node.value;
            }
            node.children.iter().map(|c| rec(c, re)).fold(0u64, |a, b| a.wrapping_add(b))
        }
        self.root
            .children
            .iter()
            .map(|c| rec(c, re))
            .fold(0u64, |a, b| a.wrapping_add(b))
    }

    fn set_search(&mut self, pattern: String) {
        match Regex::new(&pattern) {
            Ok(re) => {
                self.match_value = self.compute_match(&re);
