        let mut frames = self.frames();
        frames.retain(|f| !(f.y == 0) && re.is_match(&f.name));
        frames.sort_by(|a, b| a.y.cmp(&b.y).then(a.x.cmp(&b.x)));
        frames
    }

    fn next_match(&mut self, forward: bool) {
        let matches = self.matches_sorted();
        if matches.is_empty() {
