                (f.name.clone(), f.value)
            } else {
                ("all".to_string(), self.total)
            };
            let text = if self.zoomed.is_some() {
                format!(
                    "{} [{} samples, {}% of all, {}% of zoomed]",
                    name,
                    value,
                    pct(value, self.total),
                    pct(value, self.zoomed_value)
                )
            } else {
                format!("{} [{} samples, {}% of all]", name, value, pct(value, self.total))
            };
            v.push(info_block("Selected ", text));
        }
        if let Some(info) = &self.info {
            v.push(info_block("Info ", info.clone()));
        }
        if self.show_debug {
            v.push(info_block("Debug ", self.debug_text()));
        }
        v
    }

    fn debug_text(&self) -> String {
        let mut parts: Vec<String> = self
            .timings
            .iter()
            .map(|(k, v)| format!("{}:{:.2}ms", k, v.as_secs_f64() * 1000.0))
            .collect();
        let _ = &mut parts;
        format!("Debug: {}", parts.join(" "))
    }

    fn help_paragraph(&self) -> Paragraph<'static> {
        let bold_yellow = Style::default()
            .fg(Color::Indexed(3))
            .add_modifier(Modifier::BOLD);
        let spans: Vec<Span<'static>> = match self.view {
            View::Flamegraph => {
                let mut s = vec![
                    Span::raw(" ["),
                    Span::styled("hjkl", bold_yellow),
                    Span::raw(": move cursor] ["),
                    Span::styled("f/b", bold_yellow),
                    Span::raw(": scroll] ["),
                    Span::styled("enter/esc", bold_yellow),
                    Span::raw(": zoom] ["),
                    Span::styled("/", bold_yellow),
                    Span::raw(": search] ["),
                    Span::styled("#", bold_yellow),
                    Span::raw(": search like cursor]"),
                ];
                if self.search_pattern.is_some() {
                    s.push(Span::raw(" ["));
                    s.push(Span::styled("n/N", bold_yellow));
                    s.push(Span::raw(": next/prev search]"));
                }
                s.push(Span::raw(" ["));
                s.push(Span::styled("r", bold_yellow));
                s.push(Span::raw(": reset] ["));
                s.push(Span::styled("tab", bold_yellow));
                s.push(Span::raw(": switch view] ["));
                s.push(Span::styled("q", bold_yellow));
                s.push(Span::raw(": quit]"));
                s
            }
            View::Top => vec![
                Span::raw(" ["),
                Span::styled("j/k", bold_yellow),
                Span::raw(": move cursor] ["),
                Span::styled("f/b", bold_yellow),
                Span::raw(": scroll] ["),
                Span::styled("1", bold_yellow),
                Span::raw(": sort by total] ["),
                Span::styled("2", bold_yellow),
                Span::raw(": sort by own] ["),
                Span::styled("/", bold_yellow),
                Span::raw(": filter] ["),
                Span::styled("r", bold_yellow),
                Span::raw(": reset] ["),
                Span::styled("tab", bold_yellow),
                Span::raw(": switch view] ["),
                Span::styled("q", bold_yellow),
                Span::raw(": quit]"),
            ],
        };
        Paragraph::new(Line::from(spans)).alignment(Alignment::Center)
    }

    fn header_paragraphs(&self) -> (Paragraph<'static>, Paragraph<'static>, Paragraph<'static>) {
        let bold = Style::default().add_modifier(Modifier::BOLD);
        let bold_yellow = Style::default()
            .fg(Color::Indexed(3))
            .add_modifier(Modifier::BOLD);
        let (fg_label, fg_style, top_label, top_style) = match self.view {
            View::Flamegraph => ("[Flamegraph]", bold_yellow, "Top", bold),
            View::Top => ("Flamegraph", bold, "[Top]", bold_yellow),
        };
        let left = Paragraph::new(Line::from(vec![
            Span::raw(" "),
            Span::styled(fg_label.to_string(), fg_style),
            Span::raw(" | "),
            Span::styled(top_label.to_string(), top_style),
        ]));
        let center = Paragraph::new(Line::from(vec![Span::styled(self.name.clone(), bold)]))
            .alignment(Alignment::Center)
            .wrap(Wrap { trim: false });
        let right = Paragraph::new(Line::from(vec![Span::styled(
            "flamelens v0.3.1".to_string(),
            bold,
        )]));
        (left, center, right)
    }
}

pub fn draw(frame: &mut Frame, app: &mut App) {
    let area = frame.area();
    let (left, center, right) = app.header_paragraphs();
    let status = app.status_paragraphs();
    let help = app.help_paragraph();

    let mut constraints: Vec<Constraint> = Vec::new();
    constraints.push(Constraint::Length(3));
    constraints.push(Constraint::Min(0));
    for p in &status {
        let lc = p.line_count(area.width) as u16;
        constraints.push(Constraint::Length(lc));
    }
    constraints.push(Constraint::Length(2));

    let chunks = Layout::default()
        .direction(Direction::Vertical)
        .constraints(constraints)
        .split(area);

    let header_area = chunks[0];
    let main_area = chunks[1];
    let help_idx = chunks.len() - 1;
    let help_area = chunks[help_idx];

    // expose main geometry to app logic
    app.area_width = main_area.width;
    app.area_height = main_area.height;
    app.update_selected();

    // title block: bordered wrapper containing 20/60/20 rows
    let title_block = Block::default().borders(Borders::TOP | Borders::BOTTOM);
    let inner = title_block.inner(header_area);
    frame.render_widget(title_block, header_area);
    let cols = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Percentage(20),
            Constraint::Percentage(60),
            Constraint::Percentage(20),
        ])
        .split(inner);
    frame.render_widget(left, cols[0]);
    frame.render_widget(center, cols[1]);
    frame.render_widget(right, cols[2]);

    match app.view {
        View::Flamegraph => draw_flame(frame, app, main_area),
        View::Top => draw_top(frame, app, main_area),
    }

    for (i, p) in status.into_iter().enumerate() {
        let a = chunks[2 + i];
        if app.searching && i == 0 {
            // cursor inside the block's inner area
            let x = a.x + app.input.visual_cursor() as u16;
            let y = a.y + 1;
            if x < a.x + a.width && y < a.y + a.height {
                frame.set_cursor_position(Position { x, y });
            }
        }
        frame.render_widget(p, a);
    }

    let help_block = Block::default().borders(Borders::TOP);
    let help_inner = help_block.inner(help_area);
    frame.render_widget(help_block, help_area);
    frame.render_widget(help, help_inner);
}

// ---------- flame rendering ----------

fn truncate_to_width(s: &str, max_w: usize) -> String {
    if max_w == 0 {
        return String::new();
    }
    let mut out = String::new();
    let mut w = 0usize;
    for c in s.chars() {
        let cw = UnicodeWidthChar::width(c).unwrap_or(0);
        if w + cw > max_w {
            break;
        }
        out.push(c);
        w += cw;
    }
    out
}

fn draw_flame(frame: &mut Frame, app: &App, area: Rect) {
    let frames = app.frames();
    let buf = frame.buffer_mut();
    let no_color = std::env::var_os("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false);
    for f in &frames {
        if f.y < app.offset_y || f.y >= app.offset_y + area.height as usize {
            continue;
        }
        let row = area.y + (f.y - app.offset_y) as u16;
        let w = f.width as usize;
        if w == 0 || row >= area.y + area.height {
            continue;
        }
        let is_selected = app
            .selected
            .as_ref()
            .map(|s| s.full_name == f.full_name && s.y == f.y && s.x == f.x)
            .unwrap_or(false);
        let matched = app
            .search_regex
            .as_ref()
            .map(|re| f.y != 0 && re.is_match(&f.name))
            .unwrap_or(false);

        // determine colours
        let base = flame::base_color(&f.name, &f.full_name);
        let dimmed = if let Some(z) = &app.zoomed {
            !flame::is_ancestor_or_self(z, &f.full_name)
                // descendants of zoom have full_name with prefix z;
                // frames that are ancestors-or-self of zoom are dimmed unless zoom itself
                || (flame::is_ancestor_or_self(&f.full_name, z) && f.full_name != *z)
        } else {
            false
        };
        // Recheck dimmed rule: when zoomed, frames that are NOT descendants-or-self of zoom
        // (i.e. proper ancestors) are dimmed. Descendants are those with zoom as ancestor-or-self.
        let dimmed = if let Some(z) = &app.zoomed {
            !flame::is_ancestor_or_self(z, &f.full_name)
        } else {
            false
        };
        let _ = dimmed; // recomputed below for clarity
        let is_dimmed = if let Some(z) = &app.zoomed {
            !flame::is_ancestor_or_self(z, &f.full_name)
        } else {
            false
        };

        let (fg, bg) = if no_color {
            (Color::Reset, Color::Reset)
        } else if is_selected {
            (rgb((10, 10, 10)), rgb((250, 250, 250)))
        } else if matched && is_dimmed {
            (
                rgb((225, 225, 225)),
                rgb(((10f64 * 0.4) as u8, (35f64 * 0.4) as u8, (150f64 * 0.4) as u8)),
            )
        } else if matched {
            (rgb((225, 225, 225)), rgb((10, 35, 150)))
        } else if is_dimmed {
            let d = (
                (base.0 as f64 * 0.4) as u8,
                (base.1 as f64 * 0.4) as u8,
                (base.2 as f64 * 0.4) as u8,
            );
            let fgc = if d.1 >= 109 { (10, 10, 10) } else { (225, 225, 225) };
            (rgb(fgc), rgb(d))
        } else {
            (rgb(flame::fg_for(base)), rgb(base))
        };

        // build display text
        let disp = if w == 1 {
            ".".to_string()
        } else {
            let full = format!(" {}", f.name);
            truncate_to_width(&full, w)
        };

        // write cells
        // fill background for the whole frame width first (spaces)
        for i in 0..w {
            let x = area.x + f.x + i as u16;
            if x >= area.x + area.width {
                break;
            }
            let cell = &mut buf[(x, row)];
            cell.set_symbol(" ");
            cell.set_fg(fg);
            cell.set_bg(bg);
            cell.set_style(Style::default().fg(fg).bg(bg));
        }
        // write text with matched-substring highlights
        if !disp.is_empty() && w > 1 {
            // find highlight range within name
            let (hl_start, hl_end) = if matched {
                if let Some(re) = &app.search_regex {
                    if let Some(m) = re.find(&f.name) {
                        if m.end() > m.start() {
                            (m.start(), m.end())
                        } else {
                            (usize::MAX, usize::MAX)
                        }
                    } else {
                        (usize::MAX, usize::MAX)
                    }
                } else {
                    (usize::MAX, usize::MAX)
                }
            } else {
                (usize::MAX, usize::MAX)
            };
            // disp[0] is space, name starts at byte1
            let mut cx = area.x + f.x;
            let max_x = area.x + f.x + f.width;
            for (bi, ch) in disp.char_indices() {
                if cx >= max_x || cx >= area.x + area.width {
                    break;
                }
                let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
                if cw == 0 {
                    continue;
                }
                let cell = &mut buf[(cx, row)];
                let mut sbuf = [0u8; 4];
                cell.set_symbol(ch.encode_utf8(&mut sbuf));
                if bi >= 1 {
                    let name_bi = bi - 1;
                    if name_bi >= hl_start && name_bi < hl_end {
                        cell.set_fg(if no_color { Color::Reset } else { rgb((225, 10, 10)) });
                        if !no_color {
                            cell.set_style(
                                Style::default()
                                    .fg(rgb((225, 10, 10)))
                                    .bg(bg)
                                    .add_modifier(Modifier::BOLD),
                            );
                        }
                    }
                }
                cx += cw as u16;
            }
        } else if w == 1 {
            let x = area.x + f.x;
            if x < area.x + area.width {
                let cell = &mut buf[(x, row)];
                cell.set_symbol(".");
                cell.set_fg(fg);
                cell.set_bg(bg);
            }
        }
        let _ = UnicodeWidthStr::width(disp.as_str());
    }
}

// ---------- top rendering ----------

fn draw_top(frame: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 {
        return;
    }
    let filtered = app.filtered_stats();
    // column strings
    let mut total_strs: Vec<String> = Vec::new();
    let mut own_strs: Vec<String> = Vec::new();
    for s in &filtered {
        total_strs.push(format!("{} ({}%)", s.total, pct(s.total, app.total)));
        own_strs.push(format!("{} ({}%)", s.own, pct(s.own, app.total)));
    }
    let w_total = total_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let w_own = own_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let header = match app.sort_by {
        SortBy::Total => format!(
            "{:<w_total$}   {:<w_own$}   Name",
            "Total [▼]", "Own",
            w_total = w_total,
            w_own = w_own
        ),
        SortBy::Own => format!(
            "{:<w_total$}   {:<w_own$}   Name",
            "Total", "Own [▼]",
            w_total = w_total,
            w_own = w_own
        ),
    };
    let buf = frame.buffer_mut();
    let no_color = std::env::var_os("NO_COLOR").map(|v| !v.is_empty()).unwrap_or(false);
    // offset clamping (render-time only for display; app.top_offset also adjusted like reference)
    let vis_h = area.height as usize;
    let data_rows = vis_h.saturating_sub(1);
    // ensure selected visible
    if !filtered.is_empty() {
        // clamp selection to len-1 for display purposes via offset logic replicated in app semantics:
        // here we only adjust offset to keep selection visible using the same rules the reference
        // appears to use (bottom aligns when at edge rows). Simpler: minimal ensure-visible.
        // NOTE: app.top_offset is stored; adjust local copy and write back.
        let sel = std::cmp::min(app.top_selected_abs, filtered.len() - 1);
        let mut off = app.top_offset;
        if sel < off {
            off = sel;
        } else if data_rows > 0 && sel >= off + data_rows {
            off = sel + 1 - data_rows;
        }
        // Top/Bottom partial-scroll quirk (2-row hysteresis) is approximated by ensure-visible;
        // validated against reference tests below and refined if needed.
        app.top_offset = off;
    }
    let off = app.top_offset;

    // header row
    {
        let y = area.y;
        let style = if no_color {
            Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED)
        } else {
            Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED)
        };
        let mut cx = area.x;
        for ch in header.chars() {
            if cx >= area.x + area.width { break; }
            let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
            if cw == 0 { continue; }
            let cell = &mut buf[(cx, y)];
            let mut b = [0u8; 4];
            cell.set_symbol(ch.encode_utf8(&mut b));
            cell.set_style(style);
            cx += cw as u16;
        }
    }
    // data rows
    for i in 0..data_rows {
        let idx = off + i;
        if idx >= filtered.len() { break; }
        let y = area.y + 1 + i as u16;
        if y >= area.y + area.height { break; }
        let s = filtered[idx];
        let line = format!(
            "{:<w_total$}   {:<w_own$}   {}",
            total_strs[idx], own_strs[idx], s.name,
            w_total = w_total,
            w_own = w_own
        );
        let is_sel = idx == app.top_selected_abs;
        let mut cx = area.x;
        for ch in line.chars() {
            if cx >= area.x + area.width { break; }
            let cw = UnicodeWidthChar::width(ch).unwrap_or(0);
            if cw == 0 { continue; }
            let cell = &mut buf[(cx, y)];
            let mut b = [0u8; 4];
            cell.set_symbol(ch.encode_utf8(&mut b));
            if is_sel && !no_color {
                cell.set_bg(rgb((65, 65, 65)));
                cell.set_style(Style::default().bg(rgb((65, 65, 65))));
            }
            cx += cw as u16;
        }
        // selected row background should extend? Reference: tmux capture showed bg only on text cells (ratatui style applies to spans, rest default). Keep as above.
        let _ = s;
    }
}
