fn flame_lines(app: &App, area: Rect) -> Vec<Line<'static>> {
    let frames = app.frames();
    let no_color = std::env::var_os("NO_COLOR")
        .map(|v| !v.is_empty())
        .unwrap_or(false);
    let selected_name: Option<String> = app.selected.as_ref().map(|f| f.name.clone());
    let mut lines: Vec<Line<'static>> = Vec::new();
    for row_offset in 0..area.height as usize {
        let y = app.offset_y + row_offset;
        let mut spans: Vec<Span<'static>> = Vec::new();
        for f in frames.iter().filter(|f| f.y == y) {
            let w = f.width as usize;
            if w == 0 {
                continue;
            }
            let is_selected = app
                .selected
                .as_ref()
                .map(|s| s.full_name == f.full_name && s.y == f.y && s.x == f.x)
                .unwrap_or(false);
            let search_matched = app
                .search_regex
                .as_ref()
                .map(|re| f.y != 0 && re.is_match(&f.name))
                .unwrap_or(false);
            let base = flame::base_color(&f.name, &f.full_name);
            let is_dimmed = if let Some(z) = &app.zoomed {
                !flame::is_ancestor_or_self(z, &f.full_name)
            } else {
                false
            };
            let cursor_name_match = !is_selected
                && !search_matched
                && f.y != 0
                && selected_name.as_deref() == Some(f.name.as_str())
                && app.selected.as_ref().map(|s| s.y != 0).unwrap_or(false);
            let (fg, bg) = if no_color {
                (Color::Reset, Color::Reset)
            } else if is_selected {
                (rgb((10, 10, 10)), rgb((250, 250, 250)))
            } else if search_matched && is_dimmed {
                (
                    rgb((225, 225, 225)),
                    rgb(((10f64 * 0.4) as u8, (35f64 * 0.4) as u8, (150f64 * 0.4) as u8)),
                )
            } else if search_matched {
                (rgb((225, 225, 225)), rgb((10, 35, 150)))
            } else if cursor_name_match && is_dimmed {
                (
                    rgb((225, 225, 225)),
                    rgb(((10f64 * 0.4) as u8, (35f64 * 0.4) as u8, (150f64 * 0.4) as u8)),
                )
            } else if cursor_name_match {
                (rgb((225, 225, 225)), rgb((10, 35, 150)))
            } else if is_dimmed {
                let d = (
                    (base.0 as f64 * 0.4) as u8,
                    (base.1 as f64 * 0.4) as u8,
                    (base.2 as f64 * 0.4) as u8,
                );
                // Foreground of dimmed frames is the default terminal colour
                // in the reference for most values (tmux only showed the
                // 225 fg on 'all' whose natural fg is 225...). To replicate
                // the cell styles exactly, dimmed frames keep the original
                // frame's fg rule applied to the *undimmed* base colour but
                // ratatui Style fg = that colour.  Reference captures showed
                // e.g. dimmed "main" with no explicit fg (carried 225 from
                // "all") and dimmed "foo" likewise. That means their fg was
                // actually 225 as well? main undimmed fg is 10, foo is 225.
                // The carry-over in tmux capture is ambiguous; using fg
                // computed from the dimmed colour matches all observed
                // captures since dimmed g is always < 109.
                (rgb(flame::fg_for(d)), rgb(d))
            } else {
                (rgb(flame::fg_for(base)), rgb(base))
            };
            let style = Style::default().fg(fg).bg(bg);
            // Gap before this frame (uncovered cells) as plain spaces.
            let cur_w: usize = spans.iter().map(|sp: &Span| UnicodeWidthStr::width(sp.content.as_ref())).sum();
            if (f.x as usize) > cur_w {
                spans.push(Span::raw(" ".repeat(f.x as usize - cur_w)));
            }
            if w == 1 {
                spans.push(Span::styled(".".to_string(), style));
                continue;
            }
            // Build span(s) for this frame, splitting the search-matched
            // substring into a bold red span.
            let disp_full = format!(" {}", f.name);
            let hl = if search_matched {
                app.search_regex
                    .as_ref()
                    .and_then(|re| re.find(&f.name))
                    .filter(|m| m.end() > m.start())
                    .map(|m| (m.start() + 1, m.end() + 1))
            } else {
                None
            };
            // segments in terms of disp_full byte ranges
            let mut segs: Vec<(usize, usize, Style)> = Vec::new();
            if let Some((hs, he)) = hl {
                if hs > 0 {
                    segs.push((0, hs, style));
                }
                let hl_style = if no_color {
                    Style::default().add_modifier(Modifier::BOLD)
                } else {
                    Style::default()
                        .fg(rgb((225, 10, 10)))
                        .bg(bg)
                        .add_modifier(Modifier::BOLD)
                };
                segs.push((hs, he, hl_style));
                segs.push((he, disp_full.len(), style));
            } else {
                segs.push((0, disp_full.len(), style));
            }
            let mut emitted_w = 0usize;
            for (bs, be, st) in segs {
                if emitted_w >= w {
                    break;
                }
                let seg = &disp_full[bs..be];
                // truncate segment to remaining width
                let remain = w - emitted_w;
                let mut txt = String::new();
                let mut tw = 0usize;
                for c in seg.chars() {
                    let cw = UnicodeWidthChar::width(c).unwrap_or(0);
                    if tw + cw > remain {
                        break;
                    }
                    txt.push(c);
                    tw += cw;
                }
                if !txt.is_empty() {
                    emitted_w += tw;
                    spans.push(Span::styled(txt, st));
                }
            }
            if emitted_w < w {
                spans.push(Span::styled(" ".repeat(w - emitted_w), style));
            }
        }
        lines.push(Line::from(spans));
    }
    lines
}

fn draw_flame(frame: &mut Frame, app: &App, area: Rect) {
    let lines = flame_lines(app, area);
    frame.render_widget(Paragraph::new(lines), area);
}

// ---------- top rendering ----------

fn draw_top(frame: &mut Frame, app: &mut App, area: Rect) {
    if area.height == 0 {
        return;
    }
    let filtered: Vec<crate::stats::Stat> =
        app.filtered_stats().into_iter().cloned().collect();
    let mut total_strs: Vec<String> = Vec::new();
    let mut own_strs: Vec<String> = Vec::new();
    for s in &filtered {
        total_strs.push(format!("{} ({}%)", s.total, pct(s.total, app.total)));
        own_strs.push(format!("{} ({}%)", s.own, pct(s.own, app.total)));
    }
    let w_total = total_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let w_own = own_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let header = match app.sort_by {
        SortBy::Total => format!(
            "{:<w_total$}   {:<w_own$}   Name",
            "Total [▼]", "Own",
            w_total = w_total,
            w_own = w_own
        ),
        SortBy::Own => format!(
            "{:<w_total$}   {:<w_own$}   Name",
            "Total", "Own [▼]",
            w_total = w_total,
            w_own = w_own
        ),
    };
    let vis_h = area.height as usize;
    let data_rows = vis_h.saturating_sub(1);
    if !filtered.is_empty() && data_rows > 0 {
        let sel = std::cmp::min(app.top_selected_abs, filtered.len() - 1);
        let mut off = app.top_offset;
        if sel < off {
            off = sel;
        } else if sel >= off + data_rows {
            off = sel + 1 - data_rows;
        }
        app.top_offset = off;
    }
    let off = app.top_offset;
    let no_color = std::env::var_os("NO_COLOR")
        .map(|v| !v.is_empty())
        .unwrap_or(false);

    let mut lines: Vec<Line<'static>> = Vec::new();
    lines.push(Line::from(vec![Span::styled(
        header,
        Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED),
    )]));
    for i in 0..data_rows {
        let idx = off + i;
        if idx >= filtered.len() {
            break;
        }
        let s = &filtered[idx];
        let prefix = format!(
            "{:<w_total$}   {:<w_own$}   ",
            total_strs[idx], own_strs[idx],
            w_total = w_total,
            w_own = w_own
        );
        let is_sel = idx == app.top_selected_abs;
        let row_bg = if is_sel && !no_color {
            rgb((65, 65, 65))
        } else {
            Color::Reset
        };
        let row_style = Style::default().bg(row_bg);
        let mut spans: Vec<Span<'static>> = vec![Span::styled(prefix, row_style)];
        // name with search substring highlight
        let hl = app
            .search_regex
            .as_ref()
            .and_then(|re| re.find(&s.name))
            .filter(|m| m.end() > m.start());
        if let Some(m) = hl {
            if m.start() > 0 {
                spans.push(Span::styled(s.name[..m.start()].to_string(), row_style));
            }
            let hl_style = if no_color {
                Style::default().bg(row_bg).add_modifier(Modifier::BOLD)
            } else {
                Style::default()
                    .fg(rgb((225, 10, 10)))
                    .bg(row_bg)
                    .add_modifier(Modifier::BOLD)
            };
            spans.push(Span::styled(s.name[m.start()..m.end()].to_string(), hl_style));
            if m.end() < s.name.len() {
                spans.push(Span::styled(s.name[m.end()..].to_string(), row_style));
            }
        } else {
            spans.push(Span::styled(s.name.clone(), row_style));
        }
        lines.push(Line::from(spans));
    }
    frame.render_widget(Paragraph::new(lines), area);
}
