    if area.height == 0 {
        return;
    }
    let filtered: Vec<crate::stats::Stat> =
        app.filtered_stats().into_iter().cloned().collect();
    let mut total_strs: Vec<String> = Vec::new();
    let mut own_strs: Vec<String> = Vec::new();
    for s in &filtered {
        total_strs.push(format!("{} ({}%)", s.total, pct(s.total, app.total)));
        own_strs.push(format!("{} ({}%)", s.own, pct(s.own, app.total)));
    }
    let w_total = total_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let w_own = own_strs.iter().map(|s| s.len()).max().unwrap_or(0);
    let cols = Layout::default()
        .direction(Direction::Horizontal)
        .constraints([
            Constraint::Length(w_total as u16),
            Constraint::Length(w_own as u16),
            Constraint::Min(0),
        ])
        .spacing(3)
        .split(area);
    let (total_area, own_area, name_area) = (cols[0], cols[1], cols[2]);

    let vis_h = area.height as usize;
    let data_rows = vis_h.saturating_sub(1);
    if !filtered.is_empty() && data_rows > 0 {
        let sel = std::cmp::min(app.top_selected_abs, filtered.len() - 1);
        let mut off = app.top_offset;
        if sel < off {
            off = sel;
        } else if sel >= off + data_rows {
            off = sel + 1 - data_rows;
        }
        app.top_offset = off;
    }
    let off = app.top_offset;
    let no_color = std::env::var_os("NO_COLOR")
        .map(|v| !v.is_empty())
        .unwrap_or(false);
    let header_style = Style::default().add_modifier(Modifier::BOLD | Modifier::REVERSED);

    let render_col = |frame: &mut Frame, col_area: Rect, header: &str, cells: &[String], name_col: bool, app: &App| {
        if col_area.width == 0 || col_area.height == 0 {
            return;
        }
        let mut lines: Vec<Line<'static>> = Vec::new();
        lines.push(Line::from(vec![Span::styled(
            format!("{:<width$}", header, width = col_area.width as usize),
            header_style,
        )]));
        for i in 0..data_rows {
            let idx = off + i;
            if idx >= filtered.len() {
                break;
            }
            let s = &filtered[idx];
            let is_sel = idx == app.top_selected_abs;
            let row_bg = if is_sel && !no_color {
                rgb((65, 65, 65))
            } else {
                Color::Reset
            };
            let row_style = Style::default().bg(row_bg);
            let width = col_area.width as usize;
            let mut spans: Vec<Span<'static>> = Vec::new();
            if name_col {
                let hl_ranges: Vec<(usize, usize)> = if let Some(re) = &app.search_regex {
                    merge_ranges(
                        re.find_iter(&s.name)
                            .filter(|m| m.end() > m.start())
                            .map(|m| (m.start(), m.end()))
                            .collect(),
                    )
                } else {
                    Vec::new()
                };
                if !hl_ranges.is_empty() {
                    let hl_style = if no_color {
                        Style::default().bg(row_bg).add_modifier(Modifier::BOLD)
                    } else {
                        Style::default()
                            .fg(rgb((225, 10, 10)))
                            .bg(row_bg)
                            .add_modifier(Modifier::BOLD)
                    };
                    let mut cur = 0usize;
                    for (hs, he) in hl_ranges {
                        if hs > cur {
                            spans.push(Span::styled(s.name[cur..hs].to_string(), row_style));
                        }
                        spans.push(Span::styled(s.name[hs..he].to_string(), hl_style));
                        cur = he;
                    }
                    if cur < s.name.len() {
                        spans.push(Span::styled(s.name[cur..].to_string(), row_style));
                    }
                } else {
                    spans.push(Span::styled(s.name.clone(), row_style));
                }
                let cur_w: usize = spans
                    .iter()
                    .map(|sp| UnicodeWidthStr::width(sp.content.as_ref()))
                    .sum();
                if cur_w < width {
                    spans.push(Span::styled(" ".repeat(width - cur_w), row_style));
                }
            } else {
                spans.push(Span::styled(
                    format!("{:<width$}", cells[idx], width = width),
                    row_style,
                ));
            }
            lines.push(Line::from(spans));
        }
        frame.render_widget(Paragraph::new(lines), col_area);
    };

    let (total_hdr, own_hdr) = match app.sort_by {
        SortBy::Total => ("Total [▼]", "Own"),
        SortBy::Own => ("Total", "Own [▼]"),
    };
    render_col(frame, total_area, total_hdr, &total_strs, false, app);
    render_col(frame, own_area, own_hdr, &own_strs, false, app);
    render_col(frame, name_area, "Name", &[], true, app);
}
