pub fn build_frames(root: &Node, area_width: u16, zoom: Option<&str>) -> Vec<Frame> {
    let mut frames = Vec::new();
    if area_width == 0 {
        return frames;
    }
    let mut zoom_node: Option<&Node> = None;
    let mut zoom_value: u64 = root.value;
    if let Some(z) = zoom {
        if let Some(n) = find_by_full(root, z) {
            zoom_node = Some(n);
            zoom_value = n.value;
        }
    }
    fn rec(
        node: &Node,
        depth: usize,
        abs_x_v: u64,
        total: u64,
        area_width: u16,
        parent_render_x: u16,
        frames: &mut Vec<Frame>,
    ) {
        let mut cur_v = abs_x_v;
        let mut cur_render = parent_render_x u16_to_u32();
        fn u16_to_u32(v: u16) -> u32 { v as u32 }
        let mut cur_render = parent_render_x as u32;
        for child in &node.children {
            if child.value == 0 {
                continue;
            }
            let x = ((cur_v as f64 / total as f64) * area_width as f64) as u16;
            let w = ((child.value as f64 / total as f64) * area_width as f64) as u16;
            let render_x = cur_render as u16;
            if w > 0 {
                frames.push(Frame {
                    name: child.name.clone(),
                    full_name: child.full_name.clone(),
                    value: child.value,
                    x,
                    render_x,
                    y: depth,
                    width: w,
                });
                cur_render += w as u32;
            }
            rec(child, depth + 1, cur_v, total, area_width, render_x, frames);
            cur_v = cur_v.wrapping_add(child.value);
        }
    }
    if let Some(zn) = zoom_node {
        let mut anc: Vec<&Node> = Vec::new();
        collect_path(root, &zn.full_name, &mut anc);
        // render_x for ancestors: sequential within parent using zoom scaling
        let mut anc_render: Vec<u16> = Vec::new();
        for (i, n) in anc.iter().enumerate() {
            if i == 0 {
                anc_render.push(0);
            } else {
                let parent = anc[i - 1];
                let mut rx = anc_render[i - 1] as u32;
                for sib in &parent.children {
                    if sib.name == n.name && sib.full_name == n.full_name {
                        break;
                    }
                    if sib.value == 0 {
                        continue;
                    }
